import React, { useCallback, useState } from 'react';
import { SearchEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_MODEL_ID, VIEWPORT_LESS_TOP_HEADER } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

export default function SearchPage() {
  const [embedError, setEmbedError] = useState<string | null>(null);
  const { hiddenActions, disabledActions } = useTier();

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    setEmbedError(formatThoughtSpotEmbedError(err));
    console.error('[ThoughtSpot Search]', err);
  }, []);

  return (
    <div
      style={{
        height: VIEWPORT_LESS_TOP_HEADER,
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: '#F9FAFB',
        overflow: 'hidden',
        minHeight: 0,
      }}
    >
      <div style={{ padding: '1.5rem 2.5rem 0', flexShrink: 0 }}>
        <h1 style={{ fontSize: 26, fontWeight: 700, color: '#2c313c', margin: 0 }}>Search</h1>
        <p style={{ fontSize: 14, color: '#6B7280', margin: '8px 0 0' }}>
          Search your RedFlagAlert data model with guided tokens and filters.
        </p>
      </div>

      <div style={{ padding: '1rem 2.5rem 1.25rem', flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column' }}>
        {embedError && (
          <div
            role="alert"
            style={{
              marginBottom: '0.75rem',
              padding: '0.75rem 1rem',
              background: '#FEF2F2',
              border: '1px solid #FECACA',
              borderRadius: 8,
              fontSize: 13,
              color: '#991B1B',
              lineHeight: 1.5,
              flexShrink: 0,
            }}
          >
            <strong>Embed error:</strong> {embedError}
          </div>
        )}
        <div
          style={{
            flex: 1,
            minHeight: 0,
            backgroundColor: '#fff',
            borderRadius: 12,
            border: '1px solid #E5E7EB',
            overflow: 'hidden',
            display: 'flex',
            flexDirection: 'column',
          }}
        >
          <SearchEmbed
            dataSource={THOUGHTSPOT_MODEL_ID}
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            onError={onError}
            style={{ width: '100%', height: '100%', flex: 1, minHeight: 0, border: 'none' }}
          />
        </div>
      </div>
    </div>
  );
}
